// Per-frame update of a moby's timed state: checks its target, counts down and switches state.
void process_blarg_gunner_hits(char *m, char *p) {
    float *tm = (float *)(p + 0x20);
    char *q;
    int k;
    int r;
    if (*(unsigned char *)(m + 0x20) != 2) {
        q = MobyGetHitMessage(m, 0x330000, 0);
        r = ComputeHitResponse(m, q, tm, 0, &k, 0, 0, 4);
        if (q != 0) {
            if (*(int *)(q + 0x24) & 0x800000) {
                char *t = *(char **)(q + 0x20);
                if (t == 0) {
                    *(int *)(q + 0x2C) = 0;
                    k = 1;
                } else {
                    float f = FastDiffRots(fast_atan2(*(float *)(t + 0x10) - *(float *)(m + 0x10), *(float *)(t + 0x14) - *(float *)(m + 0x14)),
                        *(float *)(*(char **)(*(char **)(p + 0x70) + 0x78) + 0x54));
                    if (f < 1.65806282f) {
                        *(int *)(q + 0x2C) = 0;
                        k = 1;
                    }
                }
            }
        }
        switch (r) {
        case 1:
        case 2:
            *(int *)tm = 0;
            break;
        case 0: case 3: case 4: case 5: case 6: case 7: case 8: case 9: case 10: case 11:
            break;
        }
        if (k >= 2) {
            float f1 = *(float *)(q + 0x2C);
            float f0 = *tm;
            if (f0 <= f1) {
                char *x;
                *(int *)tm = 0;
                *(unsigned short *)(m + 0x34) &= 0xEFFF;
                x = *(char **)(p + 0x70);
                if (x != 0) {
                    if (*(short *)(x + 0xA6) == 0x1D) {
                        unsigned char st = x[0x20];
                        if (st != 0xFE) {
                            if (st != 0xFD) x[0x20] = 4;
                        }
                    }
                }
                SetDeathBits(m, 0, -1);
                p[0x67] = 0x78;
                RerollEffectCounter(m, (short *)(p + 0x60));
                if (*(unsigned char *)(m + 0x53) != 3) MobyBlendAnimation(m, 3, 1, 0);
                m[0x20] = 2;
            } else {
                *tm = f0 - f1;
                *(unsigned char *)(p + 0x67) = 0xFA;
                *(short *)(p + 0x26) = scale_ticks(0x3C);
                RerollEffectCounter(m, (short *)(p + 0x60));
            }
        }
    }
    *(unsigned char *)(m + 0xA4) = 0xFF;
    StepColorFade(m, p + 0x60);
}
