/* Walks the moby list: picks the on-screen target, draws the radar icons and target markers, and points an arrow at
 * off-screen pickups. */
int select_fighter_jet_target_and_draw_indicators(int a, char *p, char *a2, void *a3, float f0, float f1, float f2, char *cur, char *g) {
    float v[4];
    float mat[16];
    float u[4];
    int sx, sy, tx, ty;
    char *m;
    char *ret;
    int best;
    int *scr;
    int dx, dy, r, d2;
    float ang, dist, h, k, s, t;
    char *tab;

    m = gemlik_moby_list;
    ret = 0;
    best = 0x7FFFFFFF;
    *(int *)(p + 0xE8) = 0;
    while (m != 0) {
        tab = jet_target_marker_shape;
        scr = (int *)(screen_globals_base + 0x4A6);
        if ((((Moby *)m)->flags & 0x1000) && !(((Moby *)m)->flags & 3) && ((Moby *)m)->visible != 0 &&
            m != 0 && *(char **)&((Moby *)m)->pclass != 0 && *(short *)(*(char **)&((Moby *)m)->pclass + 0x46) == 5) {
            project_world_point_to_screen_pixels(&((Moby *)m)->pos, &sx, &sy, 0);
            dx = sx - *(int *)(p + 0xE0);
            dy = sy - *(int *)(p + 0xE4);
            if (dx < 0) dx = -dx;
            if (dy < 0) dy = -dy;
            qcopy(v, gemlik_view_basis_row1);
            FastVecScale(v, gemlik_view_basis_row1, ((Moby *)m)->bsphere.w / 1280.0f);
            FastVecAdd(v, v, &((Moby *)m)->pos);
            project_world_point_to_screen_pixels(v, &tx, &ty, 0);
            tx -= sx;
            ty -= sy;
            r = truncate_float_to_s32_r(vec_length(IntToFloat(tx * tx + ty * ty))) + 0x1C;
            if (dx < r && dy < r) {
                if (cur != 0) {
                    if (m == cur) {
                        best = 0;
                        ret = m;
                    }
                } else if (m != g) {
                    d2 = dx * dx + dy * dy;
                    if (d2 < best) {
                        best = d2;
                        ret = m;
                    }
                }
            }
        }
        switch (((Moby *)m)->oclass) {
        case 0xE0:
        case 0x4C2:
            draw_fighter_jet_radar_icon(a3, a2, m, 2, 0x75808080, *(int *)(p + 0x104));
            break;
        case 0xE4:
        case 0x4C4:
            draw_fighter_jet_radar_icon(a3, a2, m, 2, 0x75808080, *(int *)(p + 0x104));
            break;
        case 0x52:
            draw_fighter_jet_radar_icon(a3, a2, m, 1, 0x75004080, *(int *)(p + 0x104));
            break;
        case 0x53:
            draw_fighter_jet_radar_icon(a3, a2, m, 1, 0x75007080, *(int *)(p + 0x104));
            break;
        case 0x184:
        case 0x191:
        case 0x3EB:
        case 0x504:
            project_to_screen(v, &((Moby *)m)->pos);
            if (((Moby *)m)->oclass != 0x184) {
                if (((Moby *)m)->visible != 0) {
                    {
                        float x = (v[0] - scr[4]) * 0.0625f;
                        float y = (v[1] - scr[5]) * 0.0625f;
                        float ang = normalize_angle(IntToFloat(gemlik_frame_count) / 20.0f);
                        emit_transformed_2d_vertex_packet(tab, 0x1E, 0xFFFFF3, 0x500000FF, x, y, 1.0f, ang);
                    }
                    {
                        float x = (v[0] - scr[4]) * 0.0625f;
                        float y = (v[1] - scr[5]) * 0.0625f;
                        float ang = normalize_angle(IntToFloat(gemlik_frame_count) / 20.0f);
                        emit_transformed_2d_vertex_packet(tab, 0x1E, 0xFFFFF3, 0x500000FF, x, y, 1.3f, -ang);
                    }
                }
            }
            if (((Moby *)m)->oclass != 0x191) {
                if (((Moby *)m)->visible == 0) {
                    char *np = (char *)&((Moby *)m)->pos;
                    int c;
                    matrix_from_basis_rows(mat, gemlik_view_basis);
                    FastVecSub(u, np,&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.pos);
                    transform_vector(u, u, mat);
                    u[0] = -u[1];
                    u[1] = -u[2];
                    u[2] = 0.0f;
                    vec_scale_to_length(u, u, 160.0f);
                    ang = FastAddRots(fast_atan2(u[0], u[1]), 1.5707964f);
                    u[0] += 256.0f;
                    u[1] += 208.0f;
                    dist = FastVecDist((char *)a + 0x10, np);
                    h = FastAbsF(FastSubRots(fast_atan2(((Moby *)m)->pos.x - *(float *)((char *)a + 0x10),
                                                                      ((Moby *)m)->pos.y - *(float *)((char *)a + 0x14)),
                                                    *(float *)(p + 0x38)));
                    k = FastAbsF(FastSubRots(-fast_atan2(vec_distance_xy((char *)a + 0x10, np),
                                                                       ((Moby *)m)->pos.z - *(float *)((char *)a + 0x18)),
                                                    *(float *)(p + 0x34)));
                    s = vec_length(h * h + k * k);
                    t = FastAddRots(*(float *)(p + 0x114), 0.1f / (s / 3.1415927f));
                    *(float *)(p + 0x114) = t;
                    c = truncate_float_to_s32_r((FastSin(t) + 1.4f) * 53.0f);
                    if (h < 0.7853982f && k < 0.7853982f) {
                        {
                            float x = (v[0] - scr[4]) * 0.0625f;
                            float y = (v[1] - scr[5]) * 0.0625f;
                            float ang = normalize_angle(IntToFloat(gemlik_frame_count) / 20.0f);
                            emit_transformed_2d_vertex_packet(tab, 0x1E, 0xFFFFF3, 0x500000FF, x, y, 1.0f, ang);
                        }
                        {
                            float x = (v[0] - scr[4]) * 0.0625f;
                            float y = (v[1] - scr[5]) * 0.0625f;
                            float ang = normalize_angle(IntToFloat(gemlik_frame_count) / 20.0f);
                            emit_transformed_2d_vertex_packet(tab, 0x1E, 0xFFFFF3, 0x500000FF, x, y, 1.3f, -ang);
                        }
                    } else {
                        emit_transformed_2d_vertex_packet(&jet_offscreen_arrow_shape, 3, 0xFFFFF3, (c << 24) | 0x8000, u[0], u[1], 240.0f / dist + 1.5f, ang);
                    }
                }
                draw_fighter_jet_radar_icon(a3, a2, m, 0, 0x75808080, *(int *)(p + 0x104));
                if (((Moby *)m)->oclass != 0x191) {
                    *(int *)(p + 0xE8) = *(int *)(p + 0xE8) + 1;
                }
            }
            break;
        case 0x6F:
        case 0x4BE:
            if (!(((Moby *)m)->flags & 1)) {
                project_to_screen(v, &((Moby *)m)->pos);
                if (((Moby *)m)->visible != 0) {
                    {
                        float x = (v[0] - scr[4]) * 0.0625f;
                        float y = (v[1] - scr[5]) * 0.0625f;
                        float ang = normalize_angle(IntToFloat(gemlik_frame_count) / 20.0f);
                        emit_transformed_2d_vertex_packet(jet_target_marker_shape, 0x1E, 0xFFFFF3, 0xFF00FF00, x, y, 1.0f, -ang);
                    }
                }
                draw_fighter_jet_radar_icon(a3, a2, m, 1, 0x75808080, *(int *)(p + 0x104));
            }
            break;
        case 0x4BF:
            if (!(((Moby *)m)->flags & 1) && ((Moby *)m)->state >= 2) {
                project_to_screen(v, &((Moby *)m)->pos);
                if (((Moby *)m)->visible != 0) {
                    {
                        float x = (v[0] - scr[4]) * 0.0625f;
                        float y = (v[1] - scr[5]) * 0.0625f;
                        float ang = normalize_angle(IntToFloat(gemlik_frame_count) / 20.0f);
                        emit_transformed_2d_vertex_packet(jet_target_marker_shape, 0x1E, 0xFFFFF3, 0xFF00FF00, x, y, 1.0f, -ang);
                    }
                }
                draw_fighter_jet_radar_icon(a3, a2, m, 1, 0x75808080, *(int *)(p + 0x104));
            }
            break;
        case 0x185: case 0x186: case 0x187: case 0x188:
        case 0x189: case 0x18A: case 0x18B: case 0x18C:
        case 0x18F: case 0x190:
        case 0x534: case 0x535: case 0x536: case 0x537:
        case 0x538: case 0x539: case 0x53A:
            break;
        }
        m = *(char **)&((Moby *)m)->next;
    }
    return (int)ret;
}
