/* Per-frame target tracking: validates the current target, re-picks one and drops it when lost. */
void update_fighter_jet_target_tracking(int a, char *p) {
    char *g = 0;
    char *pad;
    char *t;
    char *r;
    float v[4];
    if (!(gemlik_game_mode >= 3 && gemlik_game_mode <= 4)) {
        fast_dec_timer((int *)(p + 0x8C));
    }
    if (W(p, 0x8C) != 0 && P(p, 0x88) != 0 && H(P(p, 0x88), 0xA6) == W(p, 0x124) &&
        B(P(p, 0x88), 0x20) != 0xFE && B(P(p, 0x88), 0x20) != 0xFD) {
        pad = (char *)pad_globals_base + 0x2460;
        if (B(P(p, 0x88), 0x31) != 0) {
            if (W(pad, 0x1B4) & 0x2000) {
                goto take;
            }
            if (FLAG != 0) {
                goto skip;
            }
        }
    }
    pad = (char *)pad_globals_base + 0x2460;
    if (W(pad, 0x1B4) & 0x2000) {
take:
        g = P(p, 0x88);
    }
    W(p, 0xEC) = 0;
    W(p, 0x124) = -1;
    W(p, 0x88) = 0;
skip:
    qcopy(v, gemlik_camera_rot);
    r = (char *)select_fighter_jet_target_and_draw_indicators(a, p, gemlik_camera_rot - 0x10, v, 0.19634955f, 0.19634955f, 255.0f, P(p, 0x88), g);
    if ((r != P(p, 0x88) && W(p, 0x8C) >= 0x1F5) || FLAG == 0) {
        W(p, 0xEC) = 0;
        W(p, 0x124) = -1;
        W(p, 0x88) = 0;
    }
    if (r != 0 && (P(p, 0x88) == 0 || (H(P(p, 0x88), 0xA6) != 0x3EB && H(r, 0xA6) == 0x3EB)) && FLAG != 0) {
        P(p, 0x88) = r;
        W(p, 0x124) = H(r, 0xA6);
        W(p, 0x8C) = W(p, 0x138);
    }
    if (r != P(p, 0x88)) {
        W(p, 0x118) = W(p, 0x118) + 1;
        if (scale_ticks(0x3C) < W(p, 0x118)) {
            W(p, 0xEC) = 0;
            W(p, 0x124) = -1;
            W(p, 0x88) = 0;
        }
    } else {
        W(p, 0x118) = 0;
    }
    t = P(p, 0x88);
    if (t != 0 && W(p, 0x84) == 0) {
        if (H(t, 0xA6) != W(p, 0x124) || B(t, 0x20) == 0xFE || B(t, 0x20) == 0xFD) {
            W(p, 0x88) = 0;
            W(p, 0x124) = -1;
        }
    }
}
